function tau_M_ref = mfun_imfvc_torque_reference(standby, tau_M_ref_in, p)
%MFUN_IMFVC_TORQUE_REFERENCE Block torque_reference of the control system.
%   Generated by motulator_export from the MATLAB port of motulator; the MATLAB Function
%   block of a model contains a copy of this file. The parameters are the fields of the
%   struct p, the struct of the block in the struct ctrl of the parameters of the blocks
%   of its control system (e.g., ctrl.SpeedController, see the function of the
%   parameters of the control system, e.g., fvc_params; [] as NaN).
% The external torque reference, zero in standby
tau_M_ref = tau_M_ref_in;
if standby ~= 0
    tau_M_ref = 0;
end
end
